using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace LoopPedal {
static class AtmosChecks {
 static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
 public static void Run(){try{using(var stream=new BinaryWriter(File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"atmos-reference.f32")))){var f=new MasterFx{Routing=0,ReverbMode=4,Reverb=1,Size=.65f,HallTone=.65f,ResonDetune=0};float l,r;for(int i=0;i<48000;i++)f.Process(0,0,out l,out r);double e=0;for(int i=0;i<288000;i++){f.Process(i==0?.5f:0,i==0?.5f:0,out l,out r);Check(!float.IsNaN(l)&&Math.Abs(l)<2,"Tuned finite");e+=l*l+r*r;stream.Write(l);stream.Write(r);}Check(e>.0001,"Tuned audible");}
 var bloom=new MasterFx{ReverbMode=3,Reverb=1,Size=1};double early=0,late=0;for(int i=0;i<48000;i++){float l,r;bloom.Process(0,0,out l,out r);}for(int i=0;i<288000;i++){float l,r;bloom.Process(i==0?.5f:0,i==0?.5f:0,out l,out r);Check(!float.IsNaN(l)&&Math.Abs(l)<2,"Bloom bounded");if(i<2400)early+=l*l+r*r;else if(i<24000)late+=l*l+r*r;}Check(late>early*10&&late>.00001,"Bloom rising tail");var tape=new MasterFx{DelayMode=4,Delay=1,Feedback=.85f,DelaySync=false,Time=.12f};float last=0;double maxStep=0,energy=0;for(int i=0;i<384000;i++){if(i%12000==0){tape.Time=.04f+(i%48000)/48000f*1.1f;tape.TapeDrive=(i/12000%4)/3f;tape.TapeWear=tape.TapeFlutter=(i/12000%3)/2f;}float l,r;tape.Process((float)(.08*Math.Sin(i*.04)),(float)(.08*Math.Sin(i*.04)),out l,out r);Check(!float.IsNaN(l)&&Math.Abs(l)<2,"Tape sweep finite");maxStep=Math.Max(maxStep,Math.Abs(l-last));last=l;energy+=l*l+r*r;}Check(energy>.01&&maxStep<.1,"Tape smooth/audible");
 var settings=new MasterFx{ReverbMode=4,DelayMode=4};for(int k=36;k<48;k++)ExtraFx.set(settings,k,(k-36)/11f);var copy=settings.Copy();for(int k=36;k<48;k++)Check(ExtraFx.get(copy,k)==ExtraFx.get(settings,k),"Copy control "+k);copy.ResetDefaults();for(int k=36;k<48;k++)Check(Math.Abs(ExtraFx.get(copy,k)-ExtraFx.initial(k))<1e-6,"Reset control "+k);
 var banks=new[]{new Engine(),new Engine()};banks[0].Performance=new PerformanceTimeline();settings.CopySharedSettingsTo(banks[0].Fx);banks[0].Fx.Reverb=1;var project=PerformanceProject.Capture(banks);string path=Path.Combine(Path.GetTempPath(),"Agent-Atmos-"+Guid.NewGuid()+".agw");try{project.Save(path);var restored=PerformanceProject.Load(path);Check(restored.State.Banks[0].Fx.ReverbMode==4&&restored.State.Banks[0].Fx.DelayMode==4,"Project types");for(int k=36;k<48;k++)Check(ExtraFx.get(restored.State.Banks[0].Fx,k)==ExtraFx.get(settings,k),"Project parameter "+k);}finally{if(File.Exists(path))File.Delete(path);}
 string legacy=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","diagnostics","legacy15","legacy-1.5.agw");if(File.Exists(legacy)){var old=PerformanceProject.Load(legacy);Check(old.State.Banks[0].Layers.Count>0&&old.Scenes.Slots[0]!=null,"Actual 1.5 project backward compatibility");Check(old.State.Banks[0].Fx.TapeDrive==.3f,"New controls default for old projects");}
 using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifyAtmosUi();form.Close();}
 File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"atmos-tests.txt"),"PASS Tape/Bloom/Tuned DSP, rising Bloom tail, tape time sweeps (max sample step "+maxStep+"), parameter copy/reset/project IO, live UI and MIDI targets.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"atmos-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
}
partial class Pedal {
 public void VerifyAtmosUi(){var stable=FxPanel();stable.Dock=DockStyle.None;stable.SetBounds(0,0,1120,580);Controls.Add(stable);stable.PerformLayout();Application.DoEvents();var tabs=stable.Controls.Find("MasterFxTabs",true)[0].Controls.OfType<FxTabButton>().ToArray();var bounds=tabs.Select(b=>b.RectangleToScreen(b.ClientRectangle)).ToArray();for(int repeat=0;repeat<12;repeat++)foreach(var tab in tabs){tab.PerformClick();Application.DoEvents();for(int i=0;i<tabs.Length;i++)if(tabs[i].RectangleToScreen(tabs[i].ClientRectangle)!=bounds[i])throw new Exception("FX type button moved on collapse/type change");}Controls.Remove(stable);stable.Dispose();foreach(int type in new[]{3,4,5}){loopers[0].Fx.ReverbMode=type==5?0:type;loopers[0].Fx.DelayMode=type==5?4:0;var page=FxPanel();page.Dock=DockStyle.None;page.SetBounds(0,0,1120,580);Controls.Add(page);page.BringToFront();page.PerformLayout();if(type==5)page.Controls.Find("MasterFxTabs",true)[0].Controls.OfType<FxTabButton>().First(b=>b.Effect==1).PerformClick();Application.DoEvents();int[] ids=type==3?new[]{36,37,38}:type==4?new[]{43,44,45,46,47}:new[]{39,40,41,42};foreach(int id in ids){var knob=MidiKnobs(page).FirstOrDefault(k=>(k.Tag as string)=="FX."+id);if(knob==null)throw new Exception("Missing control "+id);knob.Commit(730);if(Math.Abs(ExtraFx.get(loopers[0].Fx,id)-.73f)>(id==44?.101:1e-5))throw new Exception("Live knob dispatch");ApplyMidiValue("FX."+id,47);if(Math.Abs(ExtraFx.get(loopers[0].Fx,id)-47/127f)>(id==44?.101:1e-5))throw new Exception("MIDI dispatch");}using(var image=new Bitmap(page.Width,page.Height)){page.DrawToBitmap(image,new Rectangle(0,0,page.Width,page.Height));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,type==3?"bloom-ui.png":type==4?"tuned-ui.png":"tape-ui.png"));}Controls.Remove(page);page.Dispose();}}
}
}
